/**
 * Κατάλογος χρωμάτων τεντόπανων από τους προμηθευτές (TenCate μέσω NYFAN,
 * DAS Awning, Calbari). Οι φωτογραφίες των δειγμάτων βρίσκονται στον φάκελο
 * fabrics/ και μικραίνουν αυτόματα στο build, όπως οι φωτογραφίες έργων.
 * Τελευταία ενημέρωση από τους καταλόγους των προμηθευτών: Οκτώβριος 2026.
 */

export type FabricSupplier = "tencate" | "das" | "calbari";

export type FabricType = "Μονόχρωμα" | "Block out" | "Σχέδια" | "Ριγέ" | "Ομπρελόπανα";

export type Fabric = {
  supplier: FabricSupplier;
  collection: string;
  type: FabricType;
  name: string;
  code: string;
  /** Οικογένεια χρώματος για το φίλτρο (κενό στα σχέδια). */
  family: string;
  /** Μέσο χρώμα του δείγματος, για προβολή πριν φορτώσει η φωτογραφία. */
  hex: string;
  note: string;
  file: string;
  image: string;
  thumb: string;
};

